WITH TIPO_PESO_CORRETO AS (    SELECT V.CODPARC, TA.TIPO_PESO    FROM VINCULO_PARCEIRO_TIPO V JOIN TIPO_ARMAZENAGEM TA ON V.ID_TIPO_ARMAZENAGEM = TA.ID    WHERE V.CODPARC = :VAR_PARCEIRO_SELECIONADO    ORDER BY V.ID DESC LIMIT 1),MOVIMENTOS_UNIFICADOS AS (    SELECT        G.DATA_ENTREGA AS DT_MOV, I.AUTO_ID,        (CASE WHEN TPC.TIPO_PESO = 'Líquido' THEN I.PESO_ITEM_LIQ ELSE I.PESO_ITEM END) AS PESO,        (I.VLRUNIT * I.QTDNEG) AS VALOR,        'ENTRADA' AS TIPO_MOV    FROM GESTAO_NOTAS_APROVACAO G    JOIN IMP_ITENS_NOTAS_APRV I ON G.NUNOTA = I.NUNOTA    JOIN TIPO_PESO_CORRETO TPC ON G.CODPARC = TPC.CODPARC    WHERE G.CODPARC = :VAR_PARCEIRO_SELECIONADO AND G.ENTREGUE = 1    UNION ALL    SELECT        N.DTNEG AS DT_MOV, N.AUTO_ID,        (CASE WHEN TPC.TIPO_PESO = 'Líquido' THEN N.PESO_ITEM_LIQ ELSE N.PESO_ITEM END) AS PESO,        (N.VLRUNIT * N.QTDNEG) AS VALOR,        'SAIDA' AS TIPO_MOV    FROM IMP_NOTAS_ARMAZ N    JOIN TIPO_PESO_CORRETO TPC ON N.CODPARC = TPC.CODPARC    WHERE N.CODPARC = :VAR_PARCEIRO_SELECIONADO AND N.ATUALESTOQUE = 1),CALCULO_BASE AS (    WITH SALDO_INICIAL_VAL AS (        SELECT            GREATEST(IFNULL(SUM(CASE WHEN TIPO_MOV = 'ENTRADA' THEN PESO ELSE -PESO END), 0), 0) AS VALOR_PESO,            GREATEST(IFNULL(SUM(CASE WHEN TIPO_MOV = 'ENTRADA' THEN VALOR ELSE -VALOR END), 0), 0) AS VALOR_VALOR        FROM MOVIMENTOS_UNIFICADOS        WHERE DT_MOV < :VAR_PERIODO_INICIO    ),    MOVIMENTOS_PERIODO_DETALHADO AS (        SELECT DT_MOV, AUTO_ID, PESO, VALOR, TIPO_MOV        FROM MOVIMENTOS_UNIFICADOS        WHERE DT_MOV BETWEEN :VAR_PERIODO_INICIO AND :VAR_PERIODO_FIM    ),    SALDO_DIARIO AS (        SELECT            (SELECT VALOR_PESO FROM SALDO_INICIAL_VAL) + SUM(CASE WHEN TIPO_MOV = 'ENTRADA' THEN PESO ELSE -PESO END) OVER (ORDER BY DT_MOV, AUTO_ID) AS SALDO_ACUMULADO_PESO,            (SELECT VALOR_VALOR FROM SALDO_INICIAL_VAL) + SUM(CASE WHEN TIPO_MOV = 'ENTRADA' THEN VALOR ELSE -VALOR END) OVER (ORDER BY DT_MOV, AUTO_ID) AS SALDO_ACUMULADO_VALOR        FROM MOVIMENTOS_PERIODO_DETALHADO    ),    TODOS_OS_SALDOS AS (        SELECT VALOR_PESO AS SALDO_PESO, VALOR_VALOR AS SALDO_VALOR FROM SALDO_INICIAL_VAL        UNION ALL        SELECT SALDO_ACUMULADO_PESO, SALDO_ACUMULADO_VALOR FROM SALDO_DIARIO    )    SELECT        GREATEST(IFNULL((SELECT MAX(SALDO_PESO) FROM TODOS_OS_SALDOS), 0), 0) AS PICO_PESO,        GREATEST(IFNULL((SELECT MAX(SALDO_VALOR) FROM TODOS_OS_SALDOS), 0), 0) AS PICO_VALOR,        (SELECT IFNULL(SUM(PESO), 0) FROM MOVIMENTOS_PERIODO_DETALHADO WHERE TIPO_MOV = 'ENTRADA') AS ENTRADA_PESO,        (SELECT IFNULL(SUM(PESO), 0) FROM MOVIMENTOS_PERIODO_DETALHADO WHERE TIPO_MOV = 'SAIDA') AS SAIDA_PESO    FROM DUAL)SELECT     CP.NOME_CRITERIO AS CRITERIO, C.TIPO_VALOR, CP.TIPO_CALCULO,    ROUND(C.VALOR, 2) AS VALOR_UNITARIO,    ROUND(CASE         WHEN C.TIPO_VALOR = 'Percentual' OR CP.TIPO_CALCULO = 'Valor Declarado' THEN GREATEST(0, P.PICO_VALOR)        ELSE CASE             WHEN CP.TIPO_CALCULO = 'Entrada' THEN GREATEST(0, P.ENTRADA_PESO / 1000)            WHEN CP.TIPO_CALCULO = 'Saida' THEN GREATEST(0, P.SAIDA_PESO / 1000)            ELSE GREATEST(0, P.PICO_PESO / 1000)        END     END, 3) AS QUANTIDADE_BASE,    ROUND(CASE         WHEN CP.TIPO_CALCULO = 'Valor Declarado' THEN GREATEST(0, P.PICO_VALOR) * (C.VALOR / 100)        WHEN C.TIPO_VALOR = 'Percentual' THEN GREATEST(0, P.PICO_VALOR) * (C.VALOR / 100)        ELSE (CASE             WHEN CP.TIPO_CALCULO = 'Entrada' THEN GREATEST(0, P.ENTRADA_PESO / 1000)            WHEN CP.TIPO_CALCULO = 'Saida' THEN GREATEST(0, P.SAIDA_PESO / 1000)            ELSE GREATEST(0, P.PICO_PESO / 1000)        END) * C.VALOR     END, 2) AS VALOR_TOTALFROM VINCULO_PARCEIRO_TIPO VJOIN CRITERIO_COBRANCA C ON V.ID_TIPO_ARMAZENAGEM = C.ID_TIPO_ARMAZENAGEMJOIN CRITERIO_PADRAO CP ON C.NOME_CRITERIO = CP.NOME_CRITERIOCROSS JOIN CALCULO_BASE PWHERE V.CODPARC = :VAR_PARCEIRO_SELECIONADOORDER BY CP.NOME_CRITERIO